effect.shader:

 vec4 newLayer( vec4 a, vec4 b) { return a * (1.0 - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.0,1.0)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

     #define PI 3.14159265

     float circle(vec2 uv, float blur) {
         return smoothstep(0.0, blur, 1.0 - length(uv));
     }

/////////////////////////
 void main ()
 {

     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec2 iMouse = vec2(0.5, 0.5);
     float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;

     vec2 TanRyu;
     TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     TanRyu.y*=acLayerSize.y/acLayerSize.x;
     TanRyu /= scale;
     TanRyu *= rot2m((0.0+angle)*0.0174533);
     TanRyu += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.0,1.0)/500.0;
     vec2 scaleVec;
     scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     TanRyu /= scaleVec;

     /////////////////////////

 	vec4 fragColor;

         vec2 uv = TanRyu;

         if(acPass==0) {

         float circleWhite = circle(uv * 2.45, 1.0);
         float circleBlack = circle(uv * 2.86, 0.7);
         float c = circleWhite - circleBlack;
         c *= 6.0;

         float t = iTime * 5.0;
         c -= circle(vec2(uv.x - sin(t) * 0.85, 1.8*uv.y - cos(t) * 0.65) * 0.8, 1.0); 

         vec3 col = vec3(c) * vec3(1.0, 0.0, 0.5);
         col += vec3(smoothstep(0.2, 0.7, c)) * vec3(1.0, 1.0, 0.0);
         col += vec3(smoothstep(0.4, 0.55, c));

         gl_FragColor = vec4(col,1.0); 
         } else {

 	    vec4 xbuffer = texture2DCv(xDistBuf.texture, acScreenNorm.st);

 	    const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
         vec4 gradmap;
         float luminance = dot(xbuffer.rgb, luminanceWeighting);
         gradmap = mix(color1,color2,luminance)*xbuffer.a;
 	    vec4 factor = mix(texColorX,gradmap,1.0);

     vec4 resultfinal;
       if( blendMode==0 ) {
         resultfinal = (factor * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.0)*(1.-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
       else if( blendMode==3 ) { factor *= hardness; 
         resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
 	}
 }
